kira-bt csq -- -f ref.fa -g ann.gff in.vcf | gawk 'BEGIN{FS=OFS="\t"} /^#/ {print; next} {m=split($8,a,";"); for(i=1;i<=m;i++){ if(a[i] ~ /^(EXP|BCSQ)=/){ split(a[i],kv,"="); n=split(kv[2],v,","); asort(v); s=v[1]; for(j=2;j<=n;j++) s=s","v[j]; a[i]=kv[1]"="s } } info=a[1]; for(i=2;i<=m;i++) info=info";"a[i]; $8=info; print }' | bcftools query -f '%POS\t%REF\t%ALT\t%EXP\n%POS\t%REF\t%ALT\t%BCSQ\n\n' > out.kira.vcf
